import{_ as a,o,c as r,ae as s}from"./chunks/framework.YL6nI5ZP.js";const m=JSON.parse('{"title":"Primeros Pasos con Local SWMM","description":"","frontmatter":{},"headers":[],"relativePath":"es/tutorials/01-inicio-rapido.md","filePath":"es/tutorials/01-inicio-rapido.md"}'),i={name:"es/tutorials/01-inicio-rapido.md"};function l(n,e,t,d,c,u){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="primeros-pasos-con-local-swmm" tabindex="-1">Primeros Pasos con Local SWMM <a class="header-anchor" href="#primeros-pasos-con-local-swmm" aria-label="Permalink to &quot;Primeros Pasos con Local SWMM&quot;">​</a></h1><p>En este tutorial aprenderás qué es Local SWMM, qué necesitas para ejecutarlo y cómo abrir la aplicación y completar tu primera corrida con un modelo de muestra integrado.</p><h2 id="lo-que-haras" tabindex="-1">Lo que harás <a class="header-anchor" href="#lo-que-haras" aria-label="Permalink to &quot;Lo que harás&quot;">​</a></h2><p>Al final de esta lección habrás:</p><ul><li>abierto la aplicación web Local SWMM,</li><li>explorado sus cinco áreas principales de interfaz,</li><li>cargado una red de drenaje de muestra, y</li><li>ejecutado una corrida hidráulica e inspeccionado sus resultados.</li></ul><h2 id="que-es-local-swmm" tabindex="-1">Qué es Local SWMM <a class="header-anchor" href="#que-es-local-swmm" aria-label="Permalink to &quot;Qué es Local SWMM&quot;">​</a></h2><p>Local SWMM es una <strong>aplicación web solo de cliente</strong> para modelado hidráulico 2D y simulación de redes de aguas lluvias y aguas servidas. Todo — el editor, el generador de mallas y el motor hidráulico SWMM — corre en el navegador. El motor de simulación es el motor HydroCouple <strong>OpenSWMM</strong> compilado a <strong>WebAssembly</strong> con Emscripten.</p><p>Propiedades clave:</p><ul><li><strong>Sin backend.</strong> El único servidor es un servidor trivial de archivos estáticos + endpoint de salud (<code>server.py</code>). Sin base de datos, sin paso de build para la UI, sin bundler.</li><li><strong>Sin framework de UI.</strong> El frontend son ~15 000 líneas de JavaScript sin dependencias (scripts clásicos + IIFEs) que usan Mapbox GL JS como única librería runtime pesada.</li><li><strong>Hidráulica embebida en WASM.</strong> El motor OpenSWMM 6.0.0 está compilado de forma cruzada para <code>wasm32-emscripten</code> con dependencias C++ gestionadas por vcpkg (Eigen, HDF5, nlohmann-json, SUNDIALS).</li><li><strong>Dos backends de simulación.</strong> Una ruta de motor WASM (1D + 1D/2D acoplado) y un backend <strong>experimental WebGPU</strong> que reimplementa el solver 2D explícito de inercia local como kernels de cómputo WGSL y lo ejecuta en paralelo al motor WASM.</li><li><strong>Dos generadores de malla.</strong> Un generador heredado basado en <code>poly2tri</code> y el pipeline de producción <strong>Shewchuk Triangle WASM</strong> (npm <code>triangle-wasm</code>).</li></ul><p>La aplicación ofrece una interfaz de mapa interactiva para construir, editar y simular sistemas de drenaje urbano. Usa Mapbox GL JS para la visualización 3D de terreno y edificios, y el <a href="https://github.com/HydroCouple/openswmm.engine" target="_blank" rel="noreferrer">motor HydroCouple OpenSWMM</a> para ejecutar corridas de simulación hidráulica directamente en tu navegador gracias a WebAssembly. Puedes probarlo tú mismo en <a href="https://swmm6.is-local.org" target="_blank" rel="noreferrer">https://swmm6.is-local.org</a> — hay un video de demostración disponible en <a href="https://github.com/user-attachments/assets/6ea0af51-125d-4b7d-a6ba-e0452cfae368" target="_blank" rel="noreferrer">https://github.com/user-attachments/assets/6ea0af51-125d-4b7d-a6ba-e0452cfae368</a> (también se incluye un <code>demo.mp4</code> en el repositorio bajo <code>assets/</code>).</p><h2 id="requisitos-previos" tabindex="-1">Requisitos previos <a class="header-anchor" href="#requisitos-previos" aria-label="Permalink to &quot;Requisitos previos&quot;">​</a></h2><ul><li>Un navegador web moderno con soporte WebAssembly. <a href="https://caniuse.com/wasm" target="_blank" rel="noreferrer">Revisa aquí si puedes usarlo correctamente en tu navegador</a>.</li><li>Python 3 instalado en tu computador — solo si quieres ejecutar la aplicación desde tu propia máquina. (Node solo se necesita para <code>npm install</code> y los scripts de tooling.)</li></ul><p>No necesitas instalar nada para usar el sitio de producción, y no necesitas compilar nada desde el código fuente para esta lección.</p><h2 id="paso-1-—-abre-la-aplicacion" tabindex="-1">Paso 1 — Abre la aplicación <a class="header-anchor" href="#paso-1-—-abre-la-aplicacion" aria-label="Permalink to &quot;Paso 1 — Abre la aplicación&quot;">​</a></h2><p>La forma más rápida de empezar es el sitio de producción: <strong><a href="https://swmm6.is-local.org" target="_blank" rel="noreferrer">https://swmm6.is-local.org</a></strong>.</p><p>Si prefieres ejecutar la aplicación en tu propio computador, sigue primero la guía <a href="./../how-to/01-ejecutar-localmente">Cómo Ejecutar la Aplicación Localmente</a> y luego vuelve.</p><h2 id="paso-2-—-conoce-la-interfaz" tabindex="-1">Paso 2 — Conoce la interfaz <a class="header-anchor" href="#paso-2-—-conoce-la-interfaz" aria-label="Permalink to &quot;Paso 2 — Conoce la interfaz&quot;">​</a></h2><p>La interfaz de usuario contiene cinco áreas principales:</p><ul><li><strong>Barra de Herramientas Superior</strong>: realiza operaciones de archivo, cambia las opciones de simulación y ejecuta corridas.</li><li><strong>Paleta de Herramientas Izquierda</strong>: selecciona objetos del mapa o dibuja elementos de red.</li><li><strong>Vista de Mapa</strong>: ve y edita tu red de drenaje sobre mapas 2D o 3D interactivos.</li><li><strong>Panel Lateral Derecho</strong>: inspecciona las propiedades de los elementos o ve las tablas de resultados de corrida.</li><li><strong>Barra de Estado Inferior</strong>: ve la herramienta seleccionada actual, los conteos de elementos y las coordenadas del cursor.</li></ul><h2 id="paso-3-—-carga-un-modelo-de-muestra" tabindex="-1">Paso 3 — Carga un modelo de muestra <a class="header-anchor" href="#paso-3-—-carga-un-modelo-de-muestra" aria-label="Permalink to &quot;Paso 3 — Carga un modelo de muestra&quot;">​</a></h2><p>El proyecto incluye modelos de muestra preconfigurados:</p><ol><li>En la <strong>Barra de Herramientas Superior</strong>, abre el menú desplegable <strong>Open Model ▾</strong>.</li><li>Elige <strong>Load Sample Models</strong>.</li><li>Carga <strong>Bellinge Web</strong> (las alternativas son <strong>Bellinge Self-Contained</strong> y <strong>Bellinge No Pervious</strong>).</li></ol><p>Ahora deberías ver la red de referencia en el mapa. <strong>Bellinge Web</strong> es la red de referencia usada en toda la suite de pruebas.</p><h2 id="paso-4-—-ejecuta-la-corrida" tabindex="-1">Paso 4 — Ejecuta la corrida <a class="header-anchor" href="#paso-4-—-ejecuta-la-corrida" aria-label="Permalink to &quot;Paso 4 — Ejecuta la corrida&quot;">​</a></h2><ol><li>Pulsa <strong>Run</strong> en la <strong>Barra de Herramientas Superior</strong>.</li><li>Supervisa el progreso en la ventana <strong>Run Status</strong>. Muestra: <ul><li><strong>Seguimiento de Progreso</strong>: porcentaje de cálculo en tiempo real y tiempo simulado (<code>Days</code> y <code>Hrs:Min</code>).</li><li><strong>Detener Corrida</strong>: pulsa <strong>Stop</strong> para detener la corrida de inmediato.</li><li><strong>Minimizar Ventana</strong>: pulsa <strong>Minimize</strong> para reducir la ventana de estado a una insignia flotante. Pulsa <strong>Expand</strong> en la insignia flotante para restaurar la ventana.</li></ul></li></ol><h2 id="paso-5-—-observa-los-resultados" tabindex="-1">Paso 5 — Observa los resultados <a class="header-anchor" href="#paso-5-—-observa-los-resultados" aria-label="Permalink to &quot;Paso 5 — Observa los resultados&quot;">​</a></h2><ul><li><strong>Panel de Control Deslizante de Tiempo</strong>: usa la barra de animación inferior para reproducir, pausar, cambiar la velocidad o arrastrar hasta un paso de tiempo específico.</li><li><strong>Pestaña Properties</strong>: haz clic en cualquier nodo o enlace para ver sus propiedades geométricas y los caudales calculados.</li><li><strong>Pestaña Results</strong>: selecciona categorías de resultados para ver tablas resumen (Node Depths, Node Inflows, Link Flows y Subcatchment Runoff).</li><li><strong>Perfil de Elevación de Agua</strong>: selecciona nodos conectados y pulsa <strong>Profile</strong> para ver un gráfico de perfil hidráulico interactivo.</li></ul><h2 id="lo-que-deberias-ver-al-final" tabindex="-1">Lo que deberías ver al final <a class="header-anchor" href="#lo-que-deberias-ver-al-final" aria-label="Permalink to &quot;Lo que deberías ver al final&quot;">​</a></h2><ul><li>Una corrida terminada: la ventana <strong>Run Status</strong> llega al 100 % y las pestañas <strong>Results</strong> y <strong>Report</strong> del panel derecho están pobladas.</li><li>Una línea de tiempo animada: el <strong>Time Slider</strong> reproduce el período simulado y los colores de los resultados se actualizan en el mapa.</li><li>Ya estás listo para construir tu propia red — continúa con <a href="./02-tu-primera-red">Construye tu Primera Red de Drenaje</a>.</li></ul>',29)])])}const g=a(i,[["render",l]]);export{m as __pageData,g as default};
